import subprocess, os, shutil, pathlib
EXE=os.path.abspath("./executable")
def setup(base):
    shutil.rmtree(base, ignore_errors=True)
    os.makedirs(base+"/data"); os.makedirs(base+"/conf")
def run(base,args, extra_env=None):
    env=dict(os.environ); env["HOME"]=base; env.pop("XDG_DATA_HOME",None); env.pop("XDG_CONFIG_HOME",None)
    if extra_env: env.update(extra_env)
    r=subprocess.run([EXE,"-D",base+"/data","-C",base+"/conf"]+args, capture_output=True, text=True, env=env)
    print("CMD",args,"exit",r.returncode)
    if r.stdout: print("OUT:",repr(r.stdout))
    if r.stderr: print("ERR:",repr(r.stderr))
    # list files
    for root,dirs,files in os.walk(base):
        for f in files:
            p=os.path.join(root,f)
            print(" file",p, os.path.getsize(p))
            try:
                print(open(p).read()[:2000])
            except: pass
    return r

base="/tmp/t2"
setup(base)
run(base,["-i", os.path.abspath("assets/ical-001.ical")])
print("--- second run query")
run(base,["-G"])
run(base,["-x"])
run(base,["-Q","--from","01/01/1980"],) # default fmt 1?
PY"}

