def gen_occurrences(rec,start,limit_date=None,count=None,include_exc=True):
    """Generate occurrence dates from start. Scanning day by day up to limit or count.
    If neither limit nor count, generator should not be used."""
    results=[]
    if rec.freq==0: sigfpe()
