def next_occurrence_on_or_after(rec,start,target):
    # used for -n recur; target is a date
    if rec.until is not None and target>rec.until: return None
    limit = rec.until if rec.until is not None else target+timedelta(days=366*5)
    # But for occurrences, we may need search beyond 5 years for yearly etc - expand limit gradually
    d=max(start,target)
