def parse_recur_braces(text):
    """Parse {...} at start of text. Returns (Recur, rest, error_msg_or_None, recur_error_file_line_type)
    Error handling is done by caller producing io messages, except some recur.c errors which are direct."""
    # text starts at '{'
    if not text.startswith('{'): return None,text,"syntax error in item repetition"
    end=text.find('}')
    if end==-1: return None,text,"missing end of recurrence"
    inside=text[1:end]
    rest=text[end+1:]
    tokens=inside.split()
    if not tokens: return None,rest,"syntax error in item repetition"
    m=re.match(r'^(-?\d+)([A-Za-z])$', tokens[0])
    if not m:
        return None,rest,"syntax error in item repetition"
    freq=int(m.group(1)); rtype=m.group(2)
    if rtype not in 'DWMY':
        # recur.c: 433 unknown character, immediate stderr no prefix, exit1
        eprint("recur.c: 433: unknown character\n"); sys.exit(1)
    rec=Recur(freq,rtype)
    if freq==0:
        sigfpe()
    idx=1
    # until
    if idx < len(tokens) and tokens[idx]=='->':
        if idx+1>=len(tokens):
            return None,rest,"syntax error in until date"
        d=parse_file_date(tokens[idx+1])
        if d is None:
            # could be illegal date? original returns syntax error in until date for missing/bad format; for illegal date maybe similar?
            return None,rest,"syntax error in until date"
        rec.until=d; idx+=2
    # groups d, w, m in that order, then !
    phases=['d','w','m','!']
    phase_idx=0
    while idx < len(tokens):
        tok=tokens[idx]
        c=tok[0]
        # determine phase for c
        if c not in phases:
            return None,rest,"missing end of recurrence"
        pi=phases.index(c)
        if pi < phase_idx:
            return None,rest,"missing end of recurrence"
        phase_idx=pi
        if c=='d':
            if not re.match(r'^d-?\d+$', tok): return None,rest,"missing end of recurrence"
            rec.bymonthday.append(int(tok[1:]))
        elif c=='w':
            if not re.match(r'^w-?\d+$', tok): return None,rest,"missing end of recurrence"
            val=int(tok[1:])
            # validation for BYDAY: observed w9 illegal for Daily. General rule: decode checks.
            # recur.c 1661 illegal BYDAY value if ??? Values beyond ??? Let's implement check based on original: plain 0-6 allowed; ordinal encodings:
            # allowed if abs(val) >=7 and abs(val)%7 in 0..6 and ordinal (abs//7) ??? for monthly up to 5, yearly up to 53.
            # w9 => 9//7=1, %7=2 -> would be ordinal 1 Tue, why illegal for Daily? Because byday for Daily should be plain only.
            # We check: if rtype in 'DW' and not (0<=val<=6): illegal. For M/Y, ordinal allowed up to?
            if rec.rtype in ('D','W'):
                if not (0<=val<=6):
                    eprint("recur.c: 1661: illegal BYDAY value\n"); sys.exit(1)
            else:
                if val>  366 or val< -366:
                    eprint("recur.c: 1661: illegal BYDAY value\n"); sys.exit(1)
            rec.byday.append(val)
        elif c=='m':
            if not re.match(r'^m-?\d+$', tok): return None,rest,"missing end of recurrence"
            val=int(tok[1:])
            if not (1<=val<=12):
                eprint("recur.c: 1679: illegal bymonth value\n"); sys.exit(1)
            rec.bymonth.append(val)
        elif c=='!':
            d=parse_file_date(tok[1:])
            if d is None: return None,rest,"missing end of recurrence"
            rec.exc.append(d)
        idx+=1
    # If inside has characters not separated? tokens split ensures. Also need ensure tokens joined equals inside normalized? Original allows tabs?
    return rec,rest,None

