def finalize_recur(rec, rrule_info, start_info, is_date_event):
    if rrule_info is None:
        # Recur created for multi-day (already until set) - validate start (pattern is daily, should pass)
        return None
    start_d=start_info['date']
    count=rrule_info['count']; until_raw=rrule_info['until_raw']
    original_until_date=None
    if until_raw is not None:
        if is_date_event:
            d=ical_parse_date_value(until_raw)
            if d is None: return "invalid until format."
            original_until_date=d; rec.until=d
        else:
            r=ical_parse_datetime_value(until_raw)
            if r is None: return "invalid until format."
            epoch,d,tsec=r; original_until_date=d
            # adjustment
            rec.until=d
            # if occurrence on d and start time > until time
            start_time=start_info['time_secs']  # normalized seconds
            until_time=tsec
            # start_info time_secs includes hour/min/sec from normalized start
            if start_time > until_time and recur_date_matches(rec,start_d,d):
                rec.until=d-timedelta(days=1)
    if count is not None:
        # generate count occurrences
        occ=gen_occurrences(rec,start_d,count=count)
        if len(occ)<count:
            return f"rrule does not match start day ({fmt_date_file(start_d)})."
        rec.until=occ[-1]
    # validation: pattern match and original until not before start
    if original_until_date is not None and original_until_date < start_d:
        return f"rrule does not match start day ({fmt_date_file(start_d)})."
    if rec.freq==0:
        sigfpe()
    if not recur_date_matches(rec,start_d,start_d):
        return f"rrule does not match start day ({fmt_date_file(start_d)})."
    return None

def build_import_note(description, description_present, location, comments, import_messages):
    has_ann = (location is not None) or (len(comments)>0) or (len(import_messages)>0)
    if not description_present and not has_ann:
        return None
    text=""
    if description_present:
        text+= (description if description is not None else "") + "\n"
    if has_ann:
        text+="-- \n"
        if location is not None:
            text+=write_annotated("Location", location)
        for c in comments:
            text+=write_annotated("Comment", c)
        for msg in import_messages:
            text+=write_annotated("Import", msg)
    return text

def write_annotated(label, value):
    # value may contain newlines; first line after "Label: ", rest indented 4 spaces.
    lines=value.split('\n')
    out=f"{label}: "+lines[0]+"\n"
    for ln in lines[1:]:
        out+="    "+ln+"\n"
    return out

