def validate_combinations(args):
    # Determine major groups
    groups=0
    if args.query: groups+=1
    if args.grep or args.purge or args.filter_mode: groups+=1
    if args.export: groups+=1
    if args.import_file is not None: groups+=1
    if args.gc: groups+=1
    if args.status: groups+=1
    if args.daemon: groups+=1
    if args.next: groups+=1
    if args.nonopts:
        fatal_args(880, "invalid argument combination")
    if groups>1:
        fatal_args(880, "invalid argument combination")
    is_query=args.query
    is_grep_group=args.grep or args.purge or args.filter_mode
    # day range only for query
    if args.range_set_dayrange and not is_query:
        fatal_args(880, "invalid argument combination")
    # Also from/to/days set via query shorthands (?) -d etc set from/days but they imply query, fine.
    # Filters only for query, grep_group, export
    if args.filter_options_set and not (is_query or is_grep_group or args.export):
        fatal_args(880, "invalid argument combination")
    # formats only for query, grep_group, or dump_imported
