def do_daemon(paths,args,cfg):
    # Implementation: fork child. Child writes pid, loads config/apts presence check; if conf or apts missing, remove pid and exit.
    # Parent returns 0 immediately.
    try:
        pid=os.fork()
    except Exception:
        return 0
    if pid>0:
        return 0
