    try:
        with open(paths.daemon_pid_file,'w') as f: f.write(f"{os.getpid()}\n")
    except Exception:
        os._exit(0)
    # if conf file or calendar file missing, exit removing pid (original behaviour)
    if not (os.path.exists(paths.conf_file) and os.path.exists(paths.calendar_file)):
        try: os.remove(paths.daemon_pid_file)
        except: pass
