    terminated=[False]
    signum_holder=[0]
    def handler(signum,frame):
        terminated[0]=True; signum_holder[0]=signum
    try:
        _sig.signal(_sig.SIGTERM, handler); _sig.signal(_sig.SIGINT, handler)
    except: pass
