    warning_secs=c_atoi(cfg.get('notification.warning','300'))
    notify_cmd=cfg.get('notification.command',"printf '\\a'")
    notify_all=cfg.get('notification.notifyall','flagged-only')
    # load store helpers defined above; we are in child after fork, can use them
    notified_ids=set()
    while not terminated[0]:
        dlog(f"sleeping at {ctime_str()} for 60 seconds")
        # sleep in small increments
        for _ in range(60):
            if terminated[0]: break
            time.sleep(1)
        if terminated[0]: break
        # check appointments
        try:
            st=DataStore(paths)
            load_data_file(st,paths,FilterMatcher(Filter(),paths.notes_dir),which=('apts',))
            now=int(time.time())
