                if not it.recur:
                    starts=[it.start]
                else:
                    _,hh,mm,ss=epoch_to_datetime_parts(it.start); tsec=hh*3600+mm*60
                    td=today_local()
                    for off in range(-1,3):
                        od=td+timedelta(days=off)
                        if od < it.start_date: continue
                        if it.recur.until and od>it.recur.until: continue
                        if od in it.recur.exc: continue
                        if recur_date_matches(it.recur,it.start_date,od): starts.append(date_to_epoch(od)+tsec)
